using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests
    {
        [Fact]
        public void Context_CanAddAndRetrieveStudent()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "User",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };

            context.Students.Add(student);
            context.SaveChanges();

            var retrieved = context.Students.Single(s => s.LastName == "User");
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal(new DateTime(2023, 1, 1), retrieved.EnrollmentDate);
        }

        [Fact]
        public void Context_CanAddAndRetrieveCourse()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var dept = new Department { DepartmentID = 1, Name = "Test", Budget = 1000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 100, Title = "Test Course", Credits = 3, DepartmentID = 1 };
            context.Courses.Add(course);
            context.SaveChanges();

            var retrieved = context.Courses.Single(c => c.CourseID == 100);
            Assert.Equal("Test Course", retrieved.Title);
            Assert.Equal(3, retrieved.Credits);
        }

        [Fact]
        public void Context_CanAddAndRetrieveInstructor()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var instructor = new Instructor
            {
                FirstMidName = "John",
                LastName = "Smith",
                HireDate = new DateTime(2020, 6, 15),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };

            context.Instructors.Add(instructor);
            context.SaveChanges();

            var retrieved = context.Instructors.Single(i => i.LastName == "Smith");
            Assert.Equal("John", retrieved.FirstMidName);
            Assert.Equal(new DateTime(2020, 6, 15), retrieved.HireDate);
        }

        [Fact]
        public void Context_CanAddAndRetrieveDepartment()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var dept = new Department
            {
                Name = "Science",
                Budget = 500000,
                StartDate = new DateTime(2010, 1, 1)
            };

            context.Departments.Add(dept);
            context.SaveChanges();

            var retrieved = context.Departments.Single(d => d.Name == "Science");
            Assert.Equal(500000, retrieved.Budget);
        }

        [Fact]
        public void Context_CanAddEnrollmentWithRelationships()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var student = new Student { FirstMidName = "A", LastName = "B", EnrollmentDate = DateTime.Now };
            context.Students.Add(student);
            var dept = new Department { DepartmentID = 1, Name = "D", Budget = 1000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 500, Title = "C", Credits = 3, DepartmentID = 1 };
            context.Courses.Add(course);
            context.SaveChanges();

            var enrollment = new Enrollment { StudentID = student.ID, CourseID = 500, Grade = Grade.B };
            context.Enrollments.Add(enrollment);
            context.SaveChanges();

            var retrieved = context.Enrollments.Include(e => e.Course).Single(e => e.CourseID == 500);
            Assert.Equal(Grade.B, retrieved.Grade);
            Assert.Equal("C", retrieved.Course.Title);
        }

        [Fact]
        public void Context_CourseAssignment_CompositeKey()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var instructor = new Instructor { FirstMidName = "A", LastName = "B", HireDate = DateTime.Now, CourseAssignments = new System.Collections.Generic.List<CourseAssignment>() };
            context.Instructors.Add(instructor);
            var dept = new Department { DepartmentID = 1, Name = "D", Budget = 1000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 600, Title = "X", Credits = 2, DepartmentID = 1 };
            context.Courses.Add(course);
            context.SaveChanges();

            var assignment = new CourseAssignment { CourseID = 600, InstructorID = instructor.ID };
            context.CourseAssignments.Add(assignment);
            context.SaveChanges();

            var retrieved = context.CourseAssignments.Single(ca => ca.CourseID == 600 && ca.InstructorID == instructor.ID);
            Assert.Equal(600, retrieved.CourseID);
        }

        [Fact]
        public void Context_OfficeAssignment_OneToOne()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var instructor = new Instructor
            {
                FirstMidName = "Office",
                LastName = "Tester",
                HireDate = DateTime.Now,
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
            };

            context.Instructors.Add(instructor);
            context.SaveChanges();

            var retrieved = context.Instructors.Include(i => i.OfficeAssignment)
                .Single(i => i.LastName == "Tester");
            Assert.NotNull(retrieved.OfficeAssignment);
            Assert.Equal("Room 101", retrieved.OfficeAssignment.Location);
        }
    }

    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_SeedsDataOnEmptyDatabase()
        {
            using var context = TestHelpers.CreateInMemoryContext();

            DbInitializer.Initialize(context);

            Assert.True(context.Students.Any());
            Assert.True(context.Instructors.Any());
            Assert.True(context.Departments.Any());
            Assert.True(context.Courses.Any());
            Assert.True(context.Enrollments.Any());
        }

        [Fact]
        public void Initialize_DoesNotReseedExistingData()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            context.Students.Add(new Student { FirstMidName = "Existing", LastName = "Student", EnrollmentDate = DateTime.Now });
            context.SaveChanges();

            DbInitializer.Initialize(context);

            // Should still have only 1 student because seeding was skipped
            Assert.Single(context.Students);
        }
    }
}
"}

{"path": "/tmp/sv-910caad4455c4c4bbe42cc56c7ed3bfe/ContosoUniversity/ContosoUniversity.Tests/PaginatedListTests.cs", "file_text": "using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_ReturnsCorrectPage()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var page = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(10, page.Count);
            Assert.Equal(1, page[0]);
            Assert.Equal(10, page[9]);
        }

        [Fact]
        public void Create_CalculatesTotalPages()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var page = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(3, page.TotalPages); // 25/10 = 2.5, ceil = 3
        }

        [Fact]
        public void Create_SecondPage_SkipsFirstPageItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var page = PaginatedList<int>.Create(source, 2, 10);

            Assert.Equal(10, page.Count);
            Assert.Equal(11, page[0]);
            Assert.Equal(20, page[9]);
        }

        [Fact]
        public void Create_LastPage_HasRemainingItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var page = PaginatedList<int>.Create(source, 3, 10);

            Assert.Equal(5, page.Count);
            Assert.Equal(21, page[0]);
            Assert.Equal(25, page[4]);
        }

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();

            var page = PaginatedList<int>.Create(source, 1, 10);

            Assert.False(page.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();

            var page = PaginatedList<int>.Create(source, 2, 10);

            Assert.True(page.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();

            var page = PaginatedList<int>.Create(source, 2, 10);

            Assert.False(page.HasNextPage);
        }

        [Fact]
        public void HasNextPage_FirstPage_ReturnsTrue()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();

            var page = PaginatedList<int>.Create(source, 1, 10);

            Assert.True(page.HasNextPage);
        }

        [Fact]
        public void PageIndex_MatchesRequestedPage()
        {
            var source = Enumerable.Range(1, 30).AsQueryable();

            var page = PaginatedList<int>.Create(source, 2, 10);

            Assert.Equal(2, page.PageIndex);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            var source = Enumerable.Empty<int>().AsQueryable();

            var page = PaginatedList<int>.Create(source, 1, 10);

            Assert.Empty(page);
            Assert.Equal(0, page.TotalPages);
        }

        [Fact]
        public void Create_SingleItem_OnePageNoNext()
        {
            var source = new[] { 42 }.AsQueryable();

            var page = PaginatedList<int>.Create(source, 1, 10);

            Assert.Single(page);
            Assert.Equal(42, page[0]);
            Assert.Equal(1, page.TotalPages);
            Assert.False(page.HasNextPage);
            Assert.False(page.HasPreviousPage);
        }
    }
}
