using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests
    {
        [Fact]
        public void Context_CanAddAndRetrieveStudent()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "User",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };

            context.Students.Add(student);
            context.SaveChanges();

            var retrieved = context.Students.Single(s => s.LastName == "User");
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal(new DateTime(2023, 1, 1), retrieved.EnrollmentDate);
        }

        [Fact]
        public void Context_CanAddAndRetrieveCourse()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var dept = new Department { DepartmentID = 1, Name = "Test", Budget = 1000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 100, Title = "Test Course", Credits = 3, DepartmentID = 1 };
            context.Courses.Add(course);
            context.SaveChanges();

            var retrieved = context.Courses.Single(c => c.CourseID == 100);
            Assert.Equal("Test Course", retrieved.Title);
            Assert.Equal(3, retrieved.Credits);
        }

