public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
        SeedInstructorData(_context);
        _controller = new InstructorsController(_context);
    }

    private static void SeedInstructorData(SchoolContext context)
    {
        var instructors = new[]
        {
            new Instructor
            {
                FirstMidName = "Kim", LastName = "Abercrombie",
                HireDate = DateTime.Parse("1995-03-11"),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { Location = "Smith 17" }
            },
            new Instructor
            {
                FirstMidName = "Fadi", LastName = "Fakhouri",
                HireDate = DateTime.Parse("2002-07-06"),
                CourseAssignments = new List<CourseAssignment>()
            },
            new Instructor
            {
                FirstMidName = "Roger", LastName = "Harui",
                HireDate = DateTime.Parse("1998-07-01"),
                CourseAssignments = new List<CourseAssignment>()
            },
        };
        context.Instructors.AddRange(instructors);
        context.SaveChanges();

        var departments = new[]
        {
            new Department { DepartmentID = 1, Name = "English", Budget = 350000, StartDate = DateTime.Parse("2007-09-01"), InstructorID = instructors[0].ID },
            new Department { DepartmentID = 2, Name = "Math", Budget = 100000, StartDate = DateTime.Parse("2007-09-01"), InstructorID = instructors[1].ID },
        };
        context.Departments.AddRange(departments);
        context.SaveChanges();

        var courses = new[]
        {
            new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 },
            new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = 2 },
        };
        context.Courses.AddRange(courses);
        context.SaveChanges();

        context.CourseAssignments.Add(new CourseAssignment { CourseID = 1050, InstructorID = instructors[0].ID });
        context.CourseAssignments.Add(new CourseAssignment { CourseID = 4022, InstructorID = instructors[1].ID });
        context.SaveChanges();

        // Add a student for enrollment
        var student = new Student { FirstMidName = "Test", LastName = "Student", EnrollmentDate = DateTime.Parse("2020-01-01") };
        context.Students.Add(student);
        context.SaveChanges();

        context.Enrollments.Add(new Enrollment { StudentID = student.ID, CourseID = 1050, Grade = Grade.A });
        context.SaveChanges();
    }

    private int GetInstructorId(string lastName) => _context.Instructors.Single(i => i.LastName == lastName).ID;

